import AppKit
import ClipCore
import Carbon.HIToolbox

/// Watches the general pasteboard and saves each new copy.
final class ClipboardMonitor {
    /// Markers apps set on secrets and throwaway copies (nspasteboard.org convention + vendor types).
    static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type", "net.antelle.keeweb",
    ]

    private let pasteboard = NSPasteboard.general
    private let store: Store
    private let onSaved: () -> Void
    private let work = DispatchQueue(label: "clipstash.capture", qos: .utility)
    private var lastChange: Int
    private var timer: Timer?

    init(store: Store, onSaved: @escaping () -> Void) {
        self.store = store
        self.onSaved = onSaved
        lastChange = pasteboard.changeCount
    }

    func start() {
        // NSPasteboard has no change notification; polling changeCount is the standard, cheap approach.
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        timer?.tolerance = 0.2
    }

    /// Call right after writing to the pasteboard ourselves so the write is not re-captured.
    func ignoreCurrent() { lastChange = pasteboard.changeCount }

    private func poll() {
        guard pasteboard.changeCount != lastChange else { return }
        lastChange = pasteboard.changeCount
        guard !Prefs.paused else { return }
        let types = Set(pasteboard.types?.map(\.rawValue) ?? [])
        guard !types.isEmpty, types.isDisjoint(with: Self.skipTypes) else { return }
        let front = NSWorkspace.shared.frontmostApplication
        let bundle = front?.bundleIdentifier
        if let bundle, Prefs.excludedApps.contains(bundle) { return }
        let app = front?.localizedName

        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            save { try $0.add(kind: .file, text: urls.map(\.path).joined(separator: "\n"), app: app, bundle: bundle) }
        } else if let text = pasteboard.string(forType: .string),
                  !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let expires = Prefs.autoExpireCodes && Classifier.isOneTimeCode(text) ? Date().addingTimeInterval(300) : nil
            save { try $0.add(kind: Classifier.kind(for: text, bundle: bundle), text: text, app: app, bundle: bundle, expires: expires) }
        } else if let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff) {
            saveImage(data, name: nil, app: app, bundle: bundle)
        }
    }

    func saveImage(_ data: Data, name: String?, app: String?, bundle: String?) {
        let limit = Prefs.maxImageBytes
        save { store in
            guard let (png, w, h) = Self.png(data), png.count <= limit else { return }
            try store.add(kind: .image, text: name ?? "Image \(w)×\(h)", png: png, app: app, bundle: bundle)
        }
    }

    private func save(_ body: @escaping (Store) throws -> Void) {
        let maxClips = Prefs.maxClips, maxBytes = Prefs.storageBytes
        work.async { [store, onSaved] in
            do {
                try body(store)
                try store.prune(maxClips: maxClips, maxImageBytes: maxBytes)
            } catch {
                NSLog("ClipStash: save failed: \(error)")
            }
            DispatchQueue.main.async(execute: onSaved)
        }
    }

    private static func png(_ data: Data) -> (Data, Int, Int)? {
        guard let rep = NSBitmapImageRep(data: data) else { return nil }
        let isPNG = data.starts(with: [0x89, 0x50, 0x4E, 0x47])
        guard let png = isPNG ? data : rep.representation(using: .png, properties: [:]) else { return nil }
        return (png, rep.pixelsWide, rep.pixelsHigh)
    }
}

enum Paster {
    static var canAutoPaste: Bool { Prefs.autoPaste && AXIsProcessTrusted() }

    /// Puts the clip on the general pasteboard. Returns false if its content is gone (e.g. image file deleted).
    static func write(_ clip: Clip, store: Store) -> Bool {
        let pb = NSPasteboard.general
        switch clip.kind {
        case .image:
            guard let url = store.imageURL(clip), let png = try? Data(contentsOf: url) else { return false }
            let item = NSPasteboardItem()
            item.setData(png, forType: .png)
            if let tiff = NSImage(data: png)?.tiffRepresentation { item.setData(tiff, forType: .tiff) }
            pb.clearContents()
            return pb.writeObjects([item])
        case .file:
            let urls = clip.filePaths.map { URL(fileURLWithPath: $0) as NSURL }
            pb.clearContents()
            return pb.writeObjects(urls)
        default:
            pb.clearContents()
            return pb.setString(clip.text ?? "", forType: .string)
        }
    }

    /// Synthesizes ⌘V into the frontmost app. Needs Accessibility permission.
    static func pressCommandV() {
        let source = CGEventSource(stateID: .combinedSessionState)
        // shortcut: virtual key 9 is "V" on QWERTY/AZERTY/QWERTZ, not Dvorak; map via the keyboard layout if that matters.
        let v = CGKeyCode(kVK_ANSI_V)
        for down in [true, false] {
            let e = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: down)
            e?.flags = .maskCommand
            e?.post(tap: .cgAnnotatedSessionEventTap)
        }
    }

    static func requestAccessibility() {
        let key = kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String
        _ = AXIsProcessTrustedWithOptions([key: true] as CFDictionary)
        NSWorkspace.shared.open(URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility")!)
    }
}

/// Adds new screenshots saved to disk (any folder Spotlight indexes) to the history.
final class ScreenshotWatcher {
    private let query = NSMetadataQuery()
    private let onFile: (URL) -> Void
    private var started = Date()

    init(onFile: @escaping (URL) -> Void) {
        self.onFile = onFile
        query.predicate = NSPredicate(format: "kMDItemIsScreenCapture == 1")
        query.searchScopes = [NSMetadataQueryLocalComputerScope]
        NotificationCenter.default.addObserver(self, selector: #selector(update(_:)),
                                               name: .NSMetadataQueryDidUpdate, object: query)
    }

    func setEnabled(_ on: Bool) {
        if on, !query.isStarted {
            started = Date()
            query.start()
        } else if !on, query.isStarted {
            query.stop()
        }
    }

    @objc private func update(_ note: Notification) {
        let added = note.userInfo?[NSMetadataQueryUpdateAddedItemsKey] as? [NSMetadataItem] ?? []
        for item in added {
            guard let path = item.value(forAttribute: NSMetadataItemPathKey) as? String,
                  let created = item.value(forAttribute: NSMetadataItemFSCreationDateKey) as? Date,
                  created >= started.addingTimeInterval(-5) else { continue }
            onFile(URL(fileURLWithPath: path))
        }
    }
}
